import React from 'react';
import clsx from 'clsx';

interface ProgressBarProps {
  progress: number;
  className?: string;
  isSelected?: boolean;
  isInProgress?: boolean;
}

const ProgressBar: React.FC<ProgressBarProps> = ({ progress, className, isInProgress }) => {
  const isComplete = progress >= 100;
  const safeProgress = Math.min(100, Math.max(0, progress));

  return (
    <div className={clsx(
      'relative overflow-hidden h-2 rounded-full',
      isInProgress 
        ? 'bg-gray-300/50 dark:bg-gray-600/50 ring-1 ring-gray-400/30 dark:ring-gray-500/30' 
        : 'progress-bar',
      className
    )}>
      <div
        className={clsx(
          'h-full transition-all duration-300',
          // Always show green if 100% complete, regardless of selection
          isComplete ? 'progress-fill-complete' : 'progress-fill'
        )}
        style={{ width: `${safeProgress}%` }}
      />
      {/* Shimmer effect for completed progress bars */}
      {isComplete && (
        <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/20 to-transparent animate-shimmer-once pointer-events-none" />
      )}
    </div>
  );
};

export default ProgressBar;