import React from 'react';
import PlanCard from './PlanCard';
import type { Plan } from '../types';

interface PlanListProps {
  plans: Plan[];
  selectedPlanId: string | null;
  onSelectPlan: (planId: string) => void;
}

const PlanList: React.FC<PlanListProps> = ({ plans, selectedPlanId, onSelectPlan }) => {
  if (plans.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center py-12 px-4">
        <div className="text-6xl mb-4">📭</div>
        <p className="text-text-secondary text-center">No plans found</p>
        <p className="text-text-tertiary text-sm text-center mt-2">
          Create a plan to get started
        </p>
      </div>
    );
  }

  const handlePlanClick = (planId: string) => {
    console.log('[PlanList] Plan clicked:', planId);
    console.log('[PlanList] Previous selected plan:', selectedPlanId);
    onSelectPlan(planId);
  };

  // Sort plans: current plan first, then others by last updated date
  const sortedPlans = [...plans].sort((a, b) => {
    // Current plan always comes first
    if (a.isTheCurrentPlan) return -1;
    if (b.isTheCurrentPlan) return 1;

    // Sort remaining plans by last updated date (most recent first)
    const dateA = new Date(a.lastUpdated || a.updatedAt || 0).getTime();
    const dateB = new Date(b.lastUpdated || b.updatedAt || 0).getTime();
    return dateB - dateA;
  });

  return (
    <div className="p-3 space-y-2" role="list" aria-label="Available plans">
      {sortedPlans.map((plan) => (
        <PlanCard
          key={plan.id}
          plan={plan}
          isSelected={plan.id === selectedPlanId}
          onClick={() => handlePlanClick(plan.id)}
        />
      ))}
    </div>
  );
};

export default PlanList;