import * as React from 'react';
import * as ToggleGroupPrimitive from '@radix-ui/react-toggle-group';
import { cn } from '@/lib/utils';

interface ToggleGroupProps {
  value: string;
  onValueChange: (value: string) => void;
  children: React.ReactNode;
  className?: string;
}

const ToggleGroup = React.forwardRef<
  React.ElementRef<typeof ToggleGroupPrimitive.Root>,
  ToggleGroupProps
>(({ value, onValueChange, children, className }, ref) => (
  <ToggleGroupPrimitive.Root
    ref={ref}
    type="single"
    value={value}
    onValueChange={(newValue) => {
      // Prevent deselection - always require a selection
      if (newValue) {
        onValueChange(newValue);
      }
    }}
    className={cn(
      'inline-flex items-center gap-1 rounded-lg p-1',
      'bg-gray-200 dark:bg-gray-800',
      className
    )}
  >
    {children}
  </ToggleGroupPrimitive.Root>
));
ToggleGroup.displayName = 'ToggleGroup';

interface StatusCounts {
  notStarted: number;
  inProgress: number;
  complete: number;
}

interface ToggleGroupItemProps {
  value: string;
  children: React.ReactNode;
  count?: number;
  /** Status-based counts for plans/fixes (not started, in progress, complete) */
  statusCounts?: StatusCounts;
  className?: string;
}

const ToggleGroupItem = React.forwardRef<
  React.ElementRef<typeof ToggleGroupPrimitive.Item>,
  ToggleGroupItemProps
>(({ value, children, count, statusCounts, className }, ref) => {
  const hasStatusCounts = statusCounts && (statusCounts.notStarted > 0 || statusCounts.inProgress > 0 || statusCounts.complete > 0);
  const hasSimpleCount = count !== undefined && count > 0;

  return (
    <ToggleGroupPrimitive.Item
      ref={ref}
      value={value}
      className={cn(
        'inline-flex items-center justify-center gap-2 rounded-md px-3 py-1.5 text-sm font-medium',
        'transition-all duration-200',
        'text-gray-600 dark:text-gray-400',
        'hover:text-gray-900 dark:hover:text-gray-200',
        'data-[state=on]:bg-white data-[state=on]:dark:bg-gray-700',
        'data-[state=on]:text-gray-900 data-[state=on]:dark:text-white',
        'data-[state=on]:shadow-md',
        'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary focus-visible:ring-offset-2',
        className
      )}
    >
      {children}
      {hasStatusCounts && (
        <span className="ml-1 inline-flex items-center gap-0.5">
          {statusCounts.notStarted > 0 && (
            <span className="rounded-full bg-gray-200 dark:bg-gray-600 px-1.5 py-0.5 text-xs font-semibold text-gray-600 dark:text-gray-300">
              {statusCounts.notStarted}
            </span>
          )}
          {statusCounts.inProgress > 0 && (
            <span className="rounded-full bg-blue-100 dark:bg-blue-900/40 px-1.5 py-0.5 text-xs font-semibold text-blue-600 dark:text-blue-400">
              {statusCounts.inProgress}
            </span>
          )}
          {statusCounts.complete > 0 && (
            <span className="rounded-full bg-green-100 dark:bg-green-900/40 px-1.5 py-0.5 text-xs font-semibold text-green-600 dark:text-green-400">
              {statusCounts.complete}
            </span>
          )}
        </span>
      )}
      {!hasStatusCounts && hasSimpleCount && (
        <span className="ml-1 rounded-full bg-primary/10 px-1.5 py-0.5 text-xs font-semibold text-primary">
          {count}
        </span>
      )}
    </ToggleGroupPrimitive.Item>
  );
});
ToggleGroupItem.displayName = 'ToggleGroupItem';

export { ToggleGroup, ToggleGroupItem };
