import React from 'react';
import { cn } from '@/lib/utils';
import { Sparkles } from 'lucide-react';
import { SelectableCard } from './ui/selectable-card';
import type { Skill } from '../types';

interface SkillListProps {
  skills: Skill[];
  selectedSkillId: string | null;
  onSelectSkill: (skillId: string) => void;
}

interface SkillCardProps {
  skill: Skill;
  isSelected: boolean;
  onClick: () => void;
}

const SkillCard: React.FC<SkillCardProps> = ({ skill, isSelected, onClick }) => {
  return (
    <SelectableCard isSelected={isSelected} onClick={onClick}>
      <div className="flex items-start gap-3">
        <div className={cn(
          'p-2 rounded-lg',
          isSelected ? 'bg-primary/10' : 'bg-muted'
        )}>
          <Sparkles className="h-4 w-4 text-primary" />
        </div>
        <div className="flex-1 min-w-0">
          <h3 className="font-medium text-sm truncate">{skill.name}</h3>
          {skill.description && (
            <p className="text-xs text-muted-foreground mt-0.5 line-clamp-2">
              {skill.description}
            </p>
          )}
          <p className="text-xs text-muted-foreground/70 mt-1 font-mono truncate">
            {skill.path}
          </p>
        </div>
      </div>
    </SelectableCard>
  );
};

const SkillList: React.FC<SkillListProps> = ({
  skills,
  selectedSkillId,
  onSelectSkill,
}) => {
  if (skills.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center py-12 px-4">
        <div className="text-6xl mb-4">✨</div>
        <p className="text-muted-foreground text-center">No skills installed</p>
        <p className="text-muted-foreground/70 text-sm text-center mt-2">
          Run <code className="px-1 bg-muted rounded">npx tiny-brain analyse</code> to install skills
        </p>
      </div>
    );
  }

  return (
    <div className="p-3 space-y-2" role="list" aria-label="Installed skills">
      {skills.map((skill) => (
        <SkillCard
          key={skill.id}
          skill={skill}
          isSelected={skill.id === selectedSkillId}
          onClick={() => onSelectSkill(skill.id)}
        />
      ))}
    </div>
  );
};

export default SkillList;
