import React from 'react';
import clsx from 'clsx';
import { useTheme } from '../contexts/ThemeContext';

const ThemeToggle: React.FC = () => {
  const { theme, setTheme } = useTheme();

  return (
    <div className="inline-flex rounded-lg bg-white/50 dark:bg-black/20 backdrop-blur-sm border border-gray-300 dark:border-gray-600 overflow-hidden">
      <button
        onClick={() => setTheme('light')}
        className={clsx(
          'px-2 py-1 text-xs transition-all',
          theme === 'light'
            ? 'bg-blue-500/20 dark:bg-blue-500/40 text-text-primary dark:text-white'
            : 'text-text-secondary dark:text-gray-400 hover:bg-black/5 dark:hover:bg-white/5'
        )}
        title="Light mode"
      >
        ☀️
      </button>
      <button
        onClick={() => setTheme('dark')}
        className={clsx(
          'px-2 py-1 text-xs transition-all border-l border-r border-gray-300 dark:border-gray-600',
          theme === 'dark'
            ? 'bg-blue-500/20 dark:bg-blue-500/40 text-text-primary dark:text-white'
            : 'text-text-secondary dark:text-gray-400 hover:bg-black/5 dark:hover:bg-white/5'
        )}
        title="Dark mode"
      >
        🌙
      </button>
      <button
        onClick={() => setTheme('system')}
        className={clsx(
          'px-2 py-1 text-xs transition-all',
          theme === 'system'
            ? 'bg-blue-500/20 dark:bg-blue-500/40 text-text-primary dark:text-white'
            : 'text-text-secondary dark:text-gray-400 hover:bg-black/5 dark:hover:bg-white/5'
        )}
        title="System preference"
      >
        💻
      </button>
    </div>
  );
};

export default ThemeToggle;