import React, { useEffect, useRef } from 'react';
import clsx from 'clsx';
import type { Feature } from '../types';

interface FeatureListProps {
  features: Feature[];
  currentFeatureNumber?: number;
  onFeatureClick?: (featureNumber: number) => void;
}

const FeatureList: React.FC<FeatureListProps> = ({ features, currentFeatureNumber, onFeatureClick }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const currentFeatureRef = useRef<HTMLDivElement>(null);

  // Scroll to current feature on mount or when current feature changes
  useEffect(() => {
    if (currentFeatureRef.current && containerRef.current) {
      // Smooth scroll the current feature to the top of the container
      currentFeatureRef.current.scrollIntoView({
        behavior: 'smooth',
        block: 'start'
      });
    }
  }, [currentFeatureNumber]);
  if (!features || features.length === 0) {
    return (
      <div className="flex items-center justify-center h-full text-text-secondary dark:text-gray-400">
        No features available
      </div>
    );
  }

  return (
    <div
      ref={containerRef}
      className="h-full overflow-y-auto space-y-2 pr-2 relative
        scrollbar-thin scrollbar-thumb-gray-400 dark:scrollbar-thumb-gray-600
        scrollbar-track-transparent"
    >
      {features.map((feature) => {
        const totalTasks = feature.tasks?.length || 0;
        const completedTasks = feature.tasks?.filter(task => task.status === 'completed')?.length || 0;
        const progress = feature.status === 'completed' ? 100 :
                        totalTasks > 0 ? Math.round((completedTasks / totalTasks) * 100) : 0;
        const isCurrentFeature = feature.number === currentFeatureNumber;

        return (
          <div
            key={feature.number}
            ref={isCurrentFeature ? currentFeatureRef : null}
            onClick={() => onFeatureClick?.(feature.number)}
            className={clsx(
              'relative rounded-lg p-3 transition-all border cursor-pointer hover:shadow-md',
              isCurrentFeature && 'ring-2 ring-primary ring-offset-2',
              feature.status === 'completed' && 'bg-green-100 dark:bg-green-900/30 border-green-300 dark:border-green-800',
              feature.status === 'tested' && 'bg-red-100 dark:bg-red-900/30 border-red-300 dark:border-red-800',
              feature.status === 'defined' && 'bg-gray-100 dark:bg-gray-800/50 border-gray-300 dark:border-gray-700'
            )}
          >
            {/* Progress fill for in-progress features */}
            {feature.status === 'tested' && progress > 0 && (
              <div
                className="absolute inset-0 bg-red-200 dark:bg-red-800/40 rounded-lg transition-all duration-300"
                style={{ width: `${progress}%` }}
              />
            )}

            <div className="relative flex items-center justify-between gap-2">
              <div className="flex items-center gap-3 min-w-0 flex-1">
                {/* Feature status icon */}
                <div className="flex-shrink-0">
                  {feature.status === 'completed' && (
                    <span className="text-green-600 dark:text-green-400 text-lg" title="GREEN: Implementation complete">✓</span>
                  )}
                  {feature.status === 'tested' && (
                    <span className="text-red-600 dark:text-red-400 text-lg" title="RED: Tests written, awaiting implementation">●</span>
                  )}
                  {feature.status === 'defined' && (
                    <span className="text-gray-400 dark:text-gray-500 text-lg" title="GRAY: Defined, no commits yet">○</span>
                  )}
                </div>

                {/* Feature info */}
                <div className="min-w-0 flex-1">
                  <div className="flex items-baseline gap-2">
                    <span className={clsx(
                      "text-xs font-medium flex-shrink-0",
                      feature.status === 'completed' && "text-green-700 dark:text-green-300",
                      feature.status === 'tested' && "text-red-700 dark:text-red-300",
                      feature.status === 'defined' && "text-gray-600 dark:text-gray-400"
                    )}>
                      Feature {feature.number}
                    </span>
                    <span className={clsx(
                      "text-sm font-semibold truncate",
                      feature.status === 'completed' && "text-green-800 dark:text-green-200",
                      feature.status === 'tested' && "text-red-800 dark:text-red-200",
                      feature.status === 'defined' && "text-gray-700 dark:text-gray-300"
                    )} title={feature.title}>
                      {feature.title}
                    </span>
                  </div>

                  {/* Task count */}
                  <div className={clsx(
                    "text-xs mt-1",
                    feature.status === 'completed' && "text-green-600 dark:text-green-400",
                    feature.status === 'tested' && "text-red-600 dark:text-red-400",
                    feature.status === 'defined' && "text-gray-500 dark:text-gray-500"
                  )}>
                    {totalTasks > 0 ? `${completedTasks}/${totalTasks} tasks` : 'No tasks'}
                  </div>
                </div>
              </div>

              {/* Progress percentage for in-progress features */}
              {feature.status === 'tested' && (
                <div className={clsx(
                  "text-sm font-bold ml-3 flex-shrink-0",
                  "text-red-700 dark:text-red-300"
                )}>
                  {progress}%
                </div>
              )}

              {/* Completed badge */}
              {feature.status === 'completed' && (
                <div className="text-xs font-medium text-green-700 dark:text-green-300 ml-3 flex-shrink-0">
                  Complete
                </div>
              )}
            </div>
          </div>
        );
      })}
    </div>
  );
};

export default FeatureList;